const { title, value, currency, group, stage, owner, contactId, description } = $.input;
if (!title || !group || !stage) throw new Error('title, group (pipeline ID), and stage are required');
const deal = { title, group, stage };
deal.value = value || 0;
deal.currency = currency || 'usd';
if (owner) deal.owner = owner;
if (contactId) deal.contact = contactId;
if (description) deal.description = description;
return { deal };

const resp = $.steps.createDeal.response || {};
const deal = resp.deal || {};
return {
  dealId: deal.id || '',
  title: deal.title || $.input.title,
  value: deal.value || 0,
  currency: deal.currency || 'usd',
  stage: deal.stage || '',
  created: !!deal.id,
  summary: deal.id ? `Created deal "${deal.title || $.input.title}"` : 'Failed to create deal'
};
